import assert from 'node:assert/strict';
import {mkdir} from 'node:fs/promises';
import {chromium} from 'playwright';
import {installConnectedFixture,signInFixture} from './connected-fixture.mjs';
const browser=await chromium.launch({executablePath:process.env.BROWSER_BIN,args:['--no-sandbox']});
try {
 const context=await browser.newContext({viewport:{width:360,height:844}});
 const fixture=await installConnectedFixture(context),page=await context.newPage();
 page.setDefaultTimeout(20000);await signInFixture(page);
 await page.goto('http://127.0.0.1:4173/settings/trading',{waitUntil:'networkidle'});
 await page.getByText('Default market execution',{exact:true}).click();
 await page.getByText('Fill all or cancel',{exact:true}).click();
 for(let i=0;i<30&&fixture.preferences.defaultMarketExecution!=='FOK';i++)await page.waitForTimeout(100);
 assert.equal(fixture.preferences.defaultMarketExecution,'FOK');
 await page.goto('http://127.0.0.1:4173/trade',{waitUntil:'networkidle'});
 assert.equal(await page.getByLabel('Execution preference',{exact:true}).count(),0);
 await page.getByLabel('Margin',{exact:true}).fill('100');
 await page.getByRole('button',{name:'Review long order'}).click();
 await page.getByText('Fill all or cancel',{exact:true}).waitFor();
 await page.getByText('Confirm Long',{exact:true}).click();
 for(let i=0;i<40&&fixture.orders.length<1;i++)await page.waitForTimeout(100);
 assert.equal(fixture.orders[0].body.type,'MARKET');assert.equal(fixture.orders[0].body.timeInForce,'FOK');
 await page.getByRole('switch',{name:'Advanced trading',exact:true}).click();
 await page.getByLabel('Execution preference',{exact:true}).click();
 await page.getByText('Fill available, cancel rest',{exact:true}).click();
 await page.getByLabel('Margin',{exact:true}).fill('100');
 await page.getByRole('button',{name:'Review long order'}).click();
 await page.getByText('Confirm Long',{exact:true}).click();
 for(let i=0;i<40&&fixture.orders.length<2;i++)await page.waitForTimeout(100);
 assert.equal(fixture.orders[1].body.timeInForce,'IOC');
 assert.equal(fixture.preferences.defaultMarketExecution,'FOK');
 await page.goto('http://127.0.0.1:4173/settings/trading',{waitUntil:'networkidle'});
 await page.getByText('Default market execution',{exact:true}).click();
 await page.getByText('Keep remainder open',{exact:true}).click();
 for(let i=0;i<30&&fixture.preferences.defaultMarketExecution!=='GTC';i++)await page.waitForTimeout(100);
 await page.goto('http://127.0.0.1:4173/trade',{waitUntil:'networkidle'});
 if(await page.getByLabel('Execution preference',{exact:true}).count())await page.getByRole('switch',{name:'Advanced trading',exact:true}).click();
 assert.equal(await page.getByLabel('Execution preference',{exact:true}).count(),0);
 await page.getByLabel('Margin',{exact:true}).fill('100');
 const submit=page.getByRole('button',{name:'Review long order'});
 assert.equal(await submit.isDisabled(),true);
 await page.getByLabel('Maximum buy price',{exact:true}).fill('5000');
 assert.equal(await submit.isEnabled(),true);await submit.click();
 await page.getByText('Keep remainder open',{exact:true}).waitFor();
 await page.getByText('Confirm Long',{exact:true}).click();
 for(let i=0;i<40&&fixture.orders.length<3;i++)await page.waitForTimeout(100);
 assert.equal(fixture.orders[2].body.type,'LIMIT');assert.equal(fixture.orders[2].body.timeInForce,'GTC');assert.equal(fixture.orders[2].body.priceTicks,'5000000000');
 assert.deepEqual(fixture.failures,[]);
 await mkdir('ui-renders',{recursive:true});await page.screenshot({path:'ui-renders/market-execution-basic.png',fullPage:true});
 await context.close();
}finally{await browser.close();}
